class Solution {
  public int[] findXSum(int[] nums, int k, int x) {
    int[] ans = new int[nums.length - k + 1];
    for (int i = 0; i < ans.length; i++) {
      int[] freq = new int[51];
      for (int j = i; j < i + k; j++) freq[nums[j]]++;
      List<Integer> values = new ArrayList<>();
      for (int v = 1; v <= 50; v++) if (freq[v] > 0) values.add(v);
      values.sort((a, b) -> freq[a] != freq[b] ? freq[b] - freq[a] : b - a);
      int sum = 0;
      for (int t = 0; t < Math.min(x, values.size()); t++) {
        sum += values.get(t) * freq[values.get(t)];
      }
      ans[i] = sum;
    }
    return ans;
  }
}
